   11	
   12	// IDGenerator creates unique identifiers with a type prefix.
   13	type IDGenerator interface {
   14		NewID(prefix string) string
   15	}
   16	
   17	// SeqIDs is a deterministic IDGenerator ("pay_000001", "ref_000002", ...).
   18	type SeqIDs struct {
   19		mu sync.Mutex
   20		n  int
   21	}
   22	
   23	// NewSeqIDs returns a sequential generator starting at 1.
   24	func NewSeqIDs() *SeqIDs { return &SeqIDs{} }
   25	
   26	// NewID returns the next identifier.
   27	func (g *SeqIDs) NewID(prefix string) string {
   28		g.mu.Lock()
   29		defer g.mu.Unlock()
   30		g.n++
   31		return fmt.Sprintf("%s_%06d", prefix, g.n)
   32	}
   33	
   34	// Config tunes the service.
   35	type Config struct {
   36		// FeeBps is the processing fee in basis points charged on every payment.
   37		FeeBps int64
   38	}
   39	
   40	// Service drives the payment lifecycle.
   41	type Service struct {
   42		repo   Repository
   43		clock  clock.Clock
   44		ids    IDGenerator
   45		events Publisher
   46		cfg    Config
   47	}
   48	
   49	// NewService wires a Service. events may be nil.
   50	func NewService(repo Repository, clk clock.Clock, ids IDGenerator, events Publisher, cfg Config) *Service {
   51		return &Service{repo: repo, clock: clk, ids: ids, events: events, cfg: cfg}
   52	}
   53	
   54	// CreateInput is the input of Create.
   55	type CreateInput struct {
   56		MerchantID string
   57		Amount     money.Amount
   58	}
   59	
   60	// Create registers a new payment in status CREATED.
   61	func (s *Service) Create(ctx context.Context, in CreateInput) (Payment, error) {
   62		if in.MerchantID == "" {
   63			return Payment{}, fmt.Errorf("%w: merchant id is required", ErrInvalidInput)
   64		}
   65		if !in.Amount.IsPositive() {
   66			return Payment{}, fmt.Errorf("%w: amount must be positive, got %s", ErrInvalidInput, in.Amount)
   67		}
   68		fee, err := money.Fee(in.Amount, s.cfg.FeeBps)
   69		if err != nil {
   70			return Payment{}, fmt.Errorf("compute fee: %w", err)
   71		}
   72		now := s.clock.Now()
   73		p := Payment{
   74			ID:         s.ids.NewID("pay"),
   75			MerchantID: in.MerchantID,
   76			Amount:     in.Amount,
   77			Fee:        fee,
   78			Status:     StatusCreated,
   79			Version:    1,
   80			CreatedAt:  now,
   81			UpdatedAt:  now,
   82		}
   83		if err := s.repo.Create(ctx, p); err != nil {
   84			return Payment{}, fmt.Errorf("create payment: %w", err)
   85		}
   86		s.publish(ctx, Event{Type: "payment.created", Payment: p})
   87		return p, nil
   88	}
   89	
   90	// Get loads a payment.
   91	func (s *Service) Get(ctx context.Context, id string) (Payment, error) {
   92		p, err := s.repo.Get(ctx, id)
   93		if err != nil {
   94			return Payment{}, fmt.Errorf("get payment %s: %w", id, err)
   95		}
   96		return p, nil
   97	}
   98	
   99	// List returns one page of a merchant's payments.
  100	func (s *Service) List(ctx context.Context, merchantID string, page Page) ([]Payment, string, error) {
  101		if merchantID == "" {
  102			return nil, "", fmt.Errorf("%w: merchant id is required", ErrInvalidInput)
  103		}
  104		ps, next, err := s.repo.ListByMerchant(ctx, merchantID, page)
  105		if err != nil {
  106			return nil, "", fmt.Errorf("list payments of %s: %w", merchantID, err)
  107		}
  108		return ps, next, nil
  109	}
  110	
  111	// Authorize moves a CREATED payment to PENDING (sent to the provider).
  112	func (s *Service) Authorize(ctx context.Context, id string) (Payment, error) {
  113		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
  114			switch p.Status {
  115			case StatusCreated:
  116				p.Status = StatusPending
  117				return Event{Type: "payment.pending"}, nil
  118			default:
  119				return Event{}, fmt.Errorf("%w: cannot authorize a %s payment", ErrInvalidTransition, p.Status)
  120			}
  121		})
  122	}
  123	
  124	// Capture moves a PENDING payment to SUCCEEDED.
  125	func (s *Service) Capture(ctx context.Context, id string) (Payment, error) {
  126		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
  127			switch p.Status {
  128			case StatusPending:
  129				p.Status = StatusSucceeded
  130				return Event{Type: "payment.succeeded"}, nil
  131			default:
  132				return Event{}, fmt.Errorf("%w: cannot capture a %s payment", ErrInvalidTransition, p.Status)
  133			}
  134		})
  135	}
  136	
  137	// Decline moves a CREATED or PENDING payment to DECLINED.
  138	func (s *Service) Decline(ctx context.Context, id, reason string) (Payment, error) {
  139		return s.mutate(ctx, id, func(p *Payment) (Event, error) {
  140			switch p.Status {
  141			case StatusCreated, StatusPending:
  142				p.Status = StatusDeclined
  143				p.DeclineReason = reason
  144				return Event{Type: "payment.declined"}, nil
  145			default:
  146				return Event{}, fmt.Errorf("%w: cannot decline a %s payment", ErrInvalidTransition, p.Status)
  147			}
  148		})
  149	}
  150	
  151	// Refund refunds amount of a SUCCEEDED payment. Partial refunds keep the
  152	// payment SUCCEEDED; once the whole amount is refunded it becomes REFUNDED.
  153	func (s *Service) Refund(ctx context.Context, id string, amount money.Amount) (Payment, Refund, error) {
  154		if !amount.IsPositive() {
  155			return Payment{}, Refund{}, fmt.Errorf("%w: refund amount must be positive, got %s", ErrInvalidInput, amount)
  156		}
  157		var refund Refund
  158		p, err := s.mutate(ctx, id, func(p *Payment) (Event, error) {
  159			switch p.Status {
  160			case StatusSucceeded:
  161			default:
  162				return Event{}, fmt.Errorf("%w: cannot refund a %s payment", ErrInvalidTransition, p.Status)
  163			}
  164			if amount.Currency != p.Amount.Currency {
  165				return Event{}, fmt.Errorf("%w: refund in %s for a %s payment", money.ErrCurrencyMismatch, amount.Currency.Code, p.Amount.Currency.Code)
  166			}
  167			if amount.Minor > p.Amount.Minor {
  168				return Event{}, fmt.Errorf("%w: requested %s, remaining %s", ErrRefundExceedsRemaining, amount, p.Remaining())
  169			}
  170			refund = Refund{ID: s.ids.NewID("ref"), Amount: amount, CreatedAt: s.clock.Now()}
  171			p.Refunded += amount.Minor
  172			p.Refunds = append(p.Refunds, refund)
  173			evType := "payment.partially_refunded"
  174			if p.Refunded == p.Amount.Minor {
  175				p.Status = StatusRefunded
  176				evType = "payment.refunded"
  177			}
  178			return Event{Type: evType, Refund: &refund}, nil
  179		})
  180		if err != nil {
  181			return Payment{}, Refund{}, err
  182		}
  183		return p, refund, nil
  184	}
  185	
  186	// mutate loads a payment, applies change and saves it with optimistic locking.
  187	func (s *Service) mutate(ctx context.Context, id string, change func(p *Payment) (Event, error)) (Payment, error) {
  188		p, err := s.repo.Get(ctx, id)
  189		if err != nil {
  190			return Payment{}, fmt.Errorf("load payment %s: %w", id, err)
  191		}
  192		ev, err := change(&p)
  193		if err != nil {
  194			return Payment{}, fmt.Errorf("payment %s: %w", id, err)
  195		}
  196		p.UpdatedAt = s.clock.Now()
  197		if err := s.repo.Update(ctx, p); err != nil {
  198			return Payment{}, fmt.Errorf("save payment %s: %w", id, err)
  199		}
