func TestRefundExceedsRemaining(t *testing.T) {
	s, rec := newTestService()
	ctx := context.Background()
	p := succeeded(t, s, 100000) // 1000.00 USD

	// First refund: 600.00 USD
	p, r1, err := s.Refund(ctx, p.ID, money.MustNew(60000, "USD"))
	if err != nil {
		t.Fatalf("first refund: %v", err)
	}
	if p.Status != StatusSucceeded || p.Refunded != 60000 || p.Remaining().Minor != 40000 || r1.Amount.Minor != 60000 {
		t.Fatalf("after first refund: status=%s refunded=%d remaining=%d", p.Status, p.Refunded, p.Remaining().Minor)
	}

	// Second refund of 600.00 USD exceeds remaining 400.00 USD
	if _, _, err := s.Refund(ctx, p.ID, money.MustNew(60000, "USD")); !errors.Is(err, ErrRefundExceedsRemaining) {
		t.Fatalf("second refund error = %v, want ErrRefundExceedsRemaining", err)
	}

	// Verify payment unchanged
	stored, err := s.Get(ctx, p.ID)
	if err != nil {
		t.Fatalf("get payment: %v", err)
	}
	if stored.Status != StatusSucceeded || stored.Refunded != 60000 || stored.Remaining().Minor != 40000 || len(stored.Refunds) != 1 {
		t.Fatalf("payment changed after failed refund: status=%s refunded=%d remaining=%d len=%d",
			stored.Status, stored.Refunded, stored.Remaining().Minor, len(stored.Refunds))
	}

	// Refunding exactly remaining amount moves payment to REFUNDED
	p, r2, err := s.Refund(ctx, p.ID, money.MustNew(40000, "USD"))
	if err != nil {
		t.Fatalf("exact remaining refund: %v", err)
	}
	if p.Status != StatusRefunded || p.Refunded != 100000 || p.Remaining().Minor != 0 || r2.Amount.Minor != 40000 {
		t.Fatalf("after exact refund: status=%s refunded=%d remaining=%d", p.Status, p.Refunded, p.Remaining().Minor)
	}

	if last := rec.events[len(rec.events)-1]; last != "payment.refunded" {
		t.Fatalf("last event = %s, want payment.refunded", last)
	}
}

