func TestRefundExceedsRemaining(t *testing.T) {
	a := newTestAPI(t)
	p := a.createSucceeded("1000.00", "USD")

	// First refund of 600.00 succeeds
	rec := a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount":"600.00"}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("first refund: %d %s", rec.Code, rec.Body)
	}
	got := decode[paymentResponse](t, rec)
	if got.RefundedAmount != "600.00" || got.RemainingAmount != "400.00" || got.Status != "SUCCEEDED" {
		t.Fatalf("unexpected payment after first refund: %+v", got)
	}

	// Second refund of 600.00 fails with 422 refund_exceeds_remaining
	rec = a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount":"600.00"}`)
	if rec.Code != http.StatusUnprocessableEntity {
		t.Fatalf("second refund code = %d, want 422: %s", rec.Code, rec.Body)
	}
	errResp := decode[errorBody](t, rec)
	if errResp.Error.Code != "refund_exceeds_remaining" {
		t.Fatalf("second refund error code = %q, want refund_exceeds_remaining", errResp.Error.Code)
	}

	// Verify payment is untouched
	rec = a.do("GET", "/payments/"+p.ID, "")
	if rec.Code != http.StatusOK {
		t.Fatalf("get payment: %d %s", rec.Code, rec.Body)
	}
	cur := decode[paymentResponse](t, rec)
	if cur.RefundedAmount != "600.00" || cur.RemainingAmount != "400.00" || cur.Status != "SUCCEEDED" || len(cur.Refunds) != 1 {
		t.Fatalf("payment modified after failed refund: %+v", cur)
	}

	// Refunding exact remaining amount (400.00) succeeds and moves to REFUNDED
	rec = a.do("POST", "/payments/"+p.ID+"/refunds", `{"amount":"400.00"}`)
	if rec.Code != http.StatusCreated {
		t.Fatalf("exact refund: %d %s", rec.Code, rec.Body)
	}
	final := decode[paymentResponse](t, rec)
	if final.RefundedAmount != "1000.00" || final.RemainingAmount != "0.00" || final.Status != "REFUNDED" || len(final.Refunds) != 2 {
		t.Fatalf("unexpected payment after full refund: %+v", final)
	}
}

